    "sedationTypeEn": "Monitored conscious sedation with standby neuro-anesthesiology or General Anesthesia with endotracheal intubation.",
    "sedationTypeHi": "न्यूरो-एनेस्थीसिया विशेषज्ञ की देखरेख में बेहोशी (General Anesthesia) अथवा गहरी शामक दवा।"
