    "indicationHi": "Extracranial Carotid Artery Stenting (CAS) with Distal Filter Embolic Protection (ट्रांसकैथेटर एम्बोलाइजेशन (सूक्ष्म नस बंदी)) बीमारी के सटीक निदान एवं न्यूनतम चीरे द्वारा उपचार हेतु।",
