    "indicationHi": "Hemodialysis Reliable Outflow (HeRO) Graft Percutaneous Insertion (इंटरवेंशनल रेडियोलॉजी प्रक्रिया) बीमारी के सटीक निदान एवं न्यूनतम चीरे द्वारा उपचार हेतु।",
