    "sedationTypeEn": "Local anesthesia with intravenous conscious sedation and antiemetic cover.",
    "sedationTypeHi": "स्थानीय सुन्नता (Local Anesthesia) एवं उल्टी-दर्द निवारक शामक दवाएं।"
