    "sedationTypeEn": "Monitored anesthesia care (MAC) with deep sedation or General Anesthesia with controlled apnea.",
    "sedationTypeHi": "गहरी बेहोशी (General Anesthesia / MAC) ताकि सांस रोककर सुई सटीक गांठ में डाली जा सके।"
