    "sedationTypeEn": "General Anesthesia or monitored conscious sedation according to individual procedure protocol.",
    "sedationTypeHi": "प्रक्रिया की जटिलता के अनुसार पूर्ण बेहोशी अथवा गहरी शामक दवा।"
